document.addEventListener("DOMContentLoaded",function(){let links=document.querySelectorAll('[id^="jdm-manual-"]');for(let i=0;i<links.length;i+=1){links[i].addEventListener("click",toggleManual,false)}});document.addEventListener("DOMContentLoaded",function(){let links=document.querySelectorAll('[id^="jdm-default-"]');for(let i=0;i<links.length;i+=1){links[i].addEventListener("click",setDefault,false)}});function setDefault(){const token=Joomla.getOptions("csrf.token","");const manual_id=this.getAttribute("data-manual-id");const url="?option=com_jdocmanual&task=manuals.setdefault&manual_id="+manual_id;window.location.replace(url)}async function toggleManual(){const token=Joomla.getOptions("csrf.token","");let url="?option=com_jdocmanual&task=manuals.toggle";let manual_name=this.getAttribute("data-manual-name");let icon_id=this.getAttribute("id");let manual_id=this.getAttribute("data-manual-id");let build_manual=document.querySelector(".data-build-name-"+manual_name);let fetch_manual=document.querySelector(".data-fetch-name-"+manual_name);let build_menu=document.querySelector(".data-build-menu-"+manual_name);let data=new URLSearchParams;data.append(token,1);data.append("manual_id",manual_id);const options={method:"POST",body:data};let response=await fetch(url,options);if(!response.ok){throw new Error(Joomla.Text._("COM_JDOCMANUAL_JS_ERROR_STATUS")+`${response.status}`)}else{let result=await response.json();data=JSON.parse(result);const innerSpan=document.querySelector("#"+icon_id+" span");if(data["result"]==="No"){innerSpan.classList.remove("icon-publish");innerSpan.classList.add("icon-unpublish");build_manual.classList.add("d-none");build_menu.classList.add("d-none");if(fetch_manual){fetch_manual.classList.add("d-none")}}else{innerSpan.classList.remove("icon-unpublish");innerSpan.classList.add("icon-publish");build_manual.classList.remove("d-none");build_menu.classList.remove("d-none");if(fetch_manual){fetch_manual.classList.remove("d-none")}}}}